/**
 * Runtime support for vecDSL programs generated for Milvus with {{sdk.typescript.package}}. Generated by vecDSL 7. Do not edit.
 */
import { readFileSync } from "node:fs";
import { extname } from "node:path";
import { ClientConfig, ConsistencyLevelEnum, FlushResult, MilvusClient, RowData } from "{{sdk.typescript.package}}";

export const SDK_PACKAGE = "{{sdk.typescript.package}}";
export const SDK_VERSION = "{{sdk.typescript.version}}";
export const SERVER_SERIES = "{{server.series}}";
const PAGE = 1000;

export type Row = Record<string, unknown>;
export type Hit = { id: unknown; score: number } & Row;

export class UnsupportedFeature extends Error {
  override name = "UnsupportedFeature";
}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

type Status = { error_code?: string | number; code?: number; reason?: string };

/** Raises on an unsuccessful Milvus status; the Node SDK reports most failures in the response, not by throwing. */
export function ok<T>(response: T): T {
  const holder = response as unknown as { status?: Status } & Status;
  const status: Status | undefined = holder && typeof holder === "object" && "status" in holder ? holder.status : holder;
  if (status && typeof status === "object") {
    const failed = (status.error_code !== undefined && status.error_code !== "Success" && status.error_code !== 0) ||
      (status.code !== undefined && status.code !== 0);
    if (failed) {
      throw new Error(`Milvus error ${status.error_code ?? status.code}: ${status.reason ?? ""}`);
    }
  }
  return response;
}

function sleep(milliseconds: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

/** Opens a client, waiting for a server that is still starting (for example a fresh docker compose up). */
const endpoints = new WeakMap<MilvusClient, ClientConfig>();

export async function connect(config: ClientConfig): Promise<MilvusClient> {
  const deadline = Date.now() + Number(process.env.VECDSL_CONNECT_TIMEOUT ?? "120") * 1000;
  for (;;) {
    const client = new MilvusClient(config);
    try {
      await client.connectPromise;
      ok(await client.getVersion());
      endpoints.set(client, config);
      return client;
    } catch (error) {
      await client.closeConnection().catch(() => undefined);
      if (Date.now() >= deadline) {
        throw error;
      }
      await sleep(2000);
    }
  }
}

const serverVersions = new WeakMap<MilvusClient, string>();

export async function serverVersion(client: MilvusClient): Promise<string> {
  let found = serverVersions.get(client);
  if (found === undefined) {
    found = String(ok(await client.getVersion()).version);
    serverVersions.set(client, found);
  }
  return found;
}

function versionTuple(text: string): number[] {
  const parts: number[] = [];
  for (const token of text.replace(/^v/, "").split(/[.+-]/)) {
    if (!/^\d+$/.test(token)) {
      break;
    }
    parts.push(Number(token));
  }
  return parts;
}

export async function isLite(client: MilvusClient): Promise<boolean> {
  return (await serverVersion(client)).startsWith("milvus_lite");
}

export async function checkServer(client: MilvusClient): Promise<string> {
  const found = await serverVersion(client);
  const expected = versionTuple(SERVER_SERIES);
  const actual = versionTuple(found).slice(0, expected.length);
  if (!(await isLite(client)) && actual.join(".") !== expected.join(".")) {
    console.warn(`program generated for Milvus ${SERVER_SERIES}.x is connected to Milvus ${found}`);
  }
  return found;
}

export async function requireServer(client: MilvusClient, feature: string): Promise<void> {
  if (await isLite(client)) {
    unsupported("milvus-lite", feature);
  }
}

export function lit(value: unknown): string {
  if (typeof value === "boolean") {
    return value ? "true" : "false";
  }
  if (typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }
  if (typeof value === "string") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(lit).join(", ")}]`;
  }
  throw new TypeError(`cannot use ${typeof value} in a Milvus filter expression`);
}

export function expr(template: string, values: Record<string, unknown>): string {
  return template.replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (match, name: string) =>
    name in values ? lit(values[name]) : match);
}

const DURATION = /^\s*(\d+(?:\.\d+)?)\s*(ms|s|m|h|d|w)\s*$/;
const DURATION_SECONDS: Record<string, number> = { ms: 0.001, s: 1, m: 60, h: 3600, d: 86400, w: 604800 };

export function timeValue(args: { value: unknown }): number {
  const { value } = args;
  if (typeof value === "number") {
    return value;
  }
  const text = String(value).trim();
  if (text === "now") {
    return Date.now() / 1000;
  }
  const match = DURATION.exec(text);
  if (match) {
    return Number(match[1]) * DURATION_SECONDS[match[2]];
  }
  const moment = Date.parse(/[zZ]|[+-]\d\d:?\d\d$/.test(text) ? text : `${text}Z`);
  if (Number.isNaN(moment)) {
    throw new TypeError(`not a time value: ${text}`);
  }
  return moment / 1000;
}

export function similarity(metric: string, distance: number): number {
  switch (metric) {
    case "L2":
      return -Math.sqrt(Math.max(distance, 0));
    case "HAMMING":
      return -distance;
    case "JACCARD":
      return 1 - distance;
    default:
      return distance;
  }
}

type SearchResponse = { results: unknown[] };

export function hits(args: {
  results: SearchResponse; metric: string; native?: boolean; max_score?: number; primary_key?: string;
}): Hit[] {
  ok(args.results);
  const first = args.results.results[0];
  const rows = (Array.isArray(first) ? first : args.results.results) as Row[];
  const result: Hit[] = [];
  for (const row of rows) {
    const { id, score, ...entity } = row as { id?: unknown; score: number } & Row;
    const value = args.native ? score : similarity(args.metric, score);
    if (args.max_score !== undefined && value > args.max_score) {
      continue;
    }
    const key = id ?? (args.primary_key ? entity[args.primary_key] : undefined);
    if (args.primary_key) {
      delete entity[args.primary_key];
    }
    result.push({ id: key, score: value, ...entity });
  }
  return result;
}

export async function hasCollection(client: MilvusClient, args: { collection_name: string }): Promise<boolean> {
  return Boolean(ok(await client.hasCollection({ collection_name: args.collection_name })).value);
}

export async function hasDatabase(client: MilvusClient, args: { db_name: string }): Promise<boolean> {
  return ok(await client.listDatabases()).db_names.includes(args.db_name);
}

export function readRecords(args: { location: string; format?: string }): Row[] {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  if (path.includes("://")) {
    unsupported("milvus", `reading records from ${args.location}; it requires server-side bulk import`);
  }
  const kind = (args.format ?? extname(path).slice(1)).toLowerCase();
  const text = readFileSync(path, "utf-8").trim();
  if (kind === "json" || kind === "jsonl" || kind === "ndjson") {
    return text.startsWith("[") ? JSON.parse(text) : text.split(/\r?\n/).filter((line) => line.trim()).map((line) => JSON.parse(line));
  }
  if (kind === "csv") {
    const [head, ...lines] = text.split(/\r?\n/);
    const names = head.split(",");
    return lines.filter((line) => line.trim()).map((line) => {
      const cells = line.split(",");
      return Object.fromEntries(names.map((name, index) => [name, cells[index]]));
    });
  }
  return unsupported("milvus", `record format ${kind}`);
}

function partition(name?: string): { partition_name?: string } {
  return name ? { partition_name: name } : {};
}

function withDefaults(rows: Row[], defaults?: Row): Row[] {
  return rows.map((row) => ({ ...(defaults ?? {}), ...row }));
}

function* batches<T>(items: T[], size: number): Generator<T[]> {
  for (let start = 0; start < items.length; start += size) {
    yield items.slice(start, start + size);
  }
}

export async function getRows(client: MilvusClient, args: {
  collection_name: string; ids: unknown[]; output_fields: string[]; partition_names?: string[];
  consistency_level?: ConsistencyLevelEnum;
}): Promise<Row[]> {
  const response = ok(await client.get({
    collection_name: args.collection_name,
    ids: args.ids as string[] | number[],
    output_fields: args.output_fields,
    ...(args.partition_names ? { partition_names: args.partition_names } : {}),
    ...(args.consistency_level ? { consistency_level: args.consistency_level } : {}),
  }));
  return response.data as Row[];
}

async function existingIds(client: MilvusClient, collection: string, primaryKey: string, ids: unknown[]): Promise<Set<string>> {
  const found = new Set<string>();
  for (const chunk of batches(ids, PAGE)) {
    for (const row of await getRows(client, { collection_name: collection, ids: chunk, output_fields: [primaryKey] })) {
      found.add(String(row[primaryKey]));
    }
  }
  return found;
}

export async function insertRows(client: MilvusClient, args: {
  collection_name: string; rows: Row[]; primary_key: string; on_conflict?: string; partition_name?: string;
  defaults?: Row; batch_size?: number;
}): Promise<{ insert_count: number; skipped: number }> {
  let records = withDefaults(args.rows, args.defaults);
  const onConflict = args.on_conflict ?? "error";
  if (onConflict === "update" || onConflict === "replace") {
    const result = await upsertRows(client, { ...args, rows: records });
    return { insert_count: result.upsert_count, skipped: 0 };
  }
  const ids = records.filter((row) => args.primary_key in row).map((row) => row[args.primary_key]);
  const duplicates = ids.length > 0 ? await existingIds(client, args.collection_name, args.primary_key, ids) : new Set<string>();
  if (duplicates.size > 0 && onConflict === "error") {
    throw new Error(`${duplicates.size} records already exist in ${args.collection_name}: ${[...duplicates].slice(0, 10).join(", ")}`);
  }
  records = records.filter((row) => !duplicates.has(String(row[args.primary_key])));
  let inserted = 0;
  for (const chunk of batches(records, args.batch_size ?? PAGE)) {
    const response = ok(await client.insert({ collection_name: args.collection_name, data: chunk as RowData[], ...partition(args.partition_name) }));
    inserted += Number(response.insert_cnt);
  }
  return { insert_count: inserted, skipped: duplicates.size };
}

export async function upsertRows(client: MilvusClient, args: {
  collection_name: string; rows: Row[]; partition_name?: string; defaults?: Row; batch_size?: number;
}): Promise<{ upsert_count: number }> {
  let upserted = 0;
  for (const chunk of batches(withDefaults(args.rows, args.defaults), args.batch_size ?? PAGE)) {
    const response = ok(await client.upsert({ collection_name: args.collection_name, data: chunk as RowData[], ...partition(args.partition_name) }));
    upserted += Number(response.upsert_cnt);
  }
  return { upsert_count: upserted };
}

async function functionOutputs(client: MilvusClient, collection: string): Promise<Set<string>> {
  const description = ok(await client.describeCollection({ collection_name: collection }));
  const functions = (description.schema as unknown as { functions?: { output_field_names?: string[] }[] }).functions ?? [];
  return new Set(functions.flatMap((fn) => fn.output_field_names ?? []));
}

export async function updateRows(client: MilvusClient, args: {
  collection_name: string; primary_key: string; ids?: unknown[]; filter?: string; values?: Row; rows?: Row[];
  mode?: string; remove?: string[]; partition_name?: string;
}): Promise<{ upsert_count: number }> {
  const replacements = new Map((args.rows ?? []).map((row) => [String(row[args.primary_key]), row]));
  let ids = args.ids;
  if ((!ids || ids.length === 0) && args.filter === undefined) {
    if (replacements.size === 0) {
      throw new Error("update requires ids, a filter or records");
    }
    ids = (args.rows ?? []).map((row) => row[args.primary_key]);
  }
  const scope = args.partition_name ? [args.partition_name] : undefined;
  const current = ids && ids.length > 0
    ? await getRows(client, { collection_name: args.collection_name, ids, output_fields: ["*"], partition_names: scope })
    : await scroll(client, { collection_name: args.collection_name, filter: args.filter, output_fields: ["*"], partition_names: scope });
  const derived = await functionOutputs(client, args.collection_name);
  const updated = current.map((row) => {
    const key = row[args.primary_key];
    const merged: Row = (args.mode ?? "merge") === "merge"
      ? Object.fromEntries(Object.entries(row).filter(([name]) => !derived.has(name)))
      : { [args.primary_key]: key };
    Object.assign(merged, replacements.get(String(key)) ?? {}, args.values ?? {});
    for (const name of args.remove ?? []) {
      merged[name] = null;
    }
    return merged;
  });
  return upsertRows(client, { collection_name: args.collection_name, rows: updated, partition_name: args.partition_name });
}

export async function deleteRows(client: MilvusClient, args: {
  collection_name: string; ids?: unknown[]; filter?: string; partition_name?: string;
}): Promise<{ delete_count: number }> {
  const target = args.ids && args.ids.length > 0 ? { ids: args.ids as string[] | number[] } : { filter: args.filter ?? "" };
  const response = ok(await client.delete({ collection_name: args.collection_name, ...target, ...partition(args.partition_name) }));
  return { delete_count: Number(response.delete_cnt) };
}

export async function count(client: MilvusClient, args: {
  collection_name: string; filter?: string; partition_names?: string[]; consistency_level?: ConsistencyLevelEnum;
}): Promise<number> {
  const response = ok(await client.query({
    collection_name: args.collection_name,
    filter: args.filter ?? "",
    output_fields: ["count(*)"],
    ...(args.partition_names ? { partition_names: args.partition_names } : {}),
    ...(args.consistency_level ? { consistency_level: args.consistency_level } : {}),
  }));
  return Number((response.data[0] as Row)["count(*)"]);
}

export async function scroll(client: MilvusClient, args: {
  collection_name: string; filter?: string; output_fields?: string[]; limit?: number; offset?: number;
  partition_names?: string[]; consistency_level?: ConsistencyLevelEnum;
}): Promise<Row[]> {
  // The Node SDK's QueryIteratorReq has no offset: the iterator reads past it and the skipped rows are dropped here.
  const skip = args.offset ?? 0;
  const iterator = await client.queryIterator({
    collection_name: args.collection_name,
    batchSize: PAGE,
    expr: args.filter ?? "",
    output_fields: args.output_fields ?? [],
    ...(args.limit !== undefined ? { limit: args.limit + skip } : {}),
    ...(args.partition_names ? { partition_names: args.partition_names } : {}),
    ...(args.consistency_level ? { consistency_level: args.consistency_level } : {}),
  });
  const rows: Row[] = [];
  for await (const batch of iterator as AsyncIterable<Row[]>) {
    rows.push(...batch);
  }
  // The iterator does not stop at its limit (Node SDK 3.0.6 returns every row): the page is cut here.
  return args.limit !== undefined ? rows.slice(skip, skip + args.limit) : rows.slice(skip);
}

export async function lookupVector(client: MilvusClient, args: { collection_name: string; field: string; id: unknown }): Promise<number[]> {
  const rows = await getRows(client, { collection_name: args.collection_name, ids: [args.id], output_fields: [args.field] });
  if (rows.length === 0) {
    throw new Error(`record ${String(args.id)} not found in ${args.collection_name}`);
  }
  return rows[0][args.field] as number[];
}

export function exampleIds(args: { positives: unknown[]; negatives?: unknown[] }): unknown[] {
  return [...args.positives, ...(args.negatives ?? [])].filter((item) => !Array.isArray(item));
}

export async function recommendVector(client: MilvusClient, args: {
  collection_name: string; field: string; positives: unknown[]; negatives?: unknown[];
}): Promise<number[]> {
  const resolve = async (items: unknown[]): Promise<number[][]> => {
    const vectors = items.filter(Array.isArray) as number[][];
    const keys = items.filter((item) => !Array.isArray(item));
    if (keys.length > 0) {
      const rows = await getRows(client, { collection_name: args.collection_name, ids: keys, output_fields: [args.field] });
      vectors.push(...rows.map((row) => row[args.field] as number[]));
    }
    return vectors;
  };
  const mean = (vectors: number[][]) => vectors[0].map((_, index) => vectors.reduce((sum, v) => sum + v[index], 0) / vectors.length);
  const positive = await resolve(args.positives);
  const negative = await resolve(args.negatives ?? []);
  if (positive.length === 0) {
    throw new Error("recommend requires at least one positive example");
  }
  const centroid = mean(positive);
  if (negative.length === 0) {
    return centroid;
  }
  const anti = mean(negative);
  return centroid.map((value, index) => 2 * value - anti[index]);
}

function pairwise(metric: string, left: number[], right: number[]): number {
  if (metric === "L2") {
    return -Math.sqrt(left.reduce((sum, value, index) => sum + (value - right[index]) ** 2, 0));
  }
  const dot = left.reduce((sum, value, index) => sum + value * right[index], 0);
  if (metric === "COSINE") {
    const norm = Math.hypot(...left) * Math.hypot(...right);
    return norm ? dot / norm : 0;
  }
  if (metric === "IP") {
    return dot;
  }
  return unsupported("milvus", `distance matrix for metric ${metric}`);
}

export async function distanceMatrix(client: MilvusClient, args: {
  collection_name: string; field: string; metric: string; primary_key: string; sample?: number; limit?: number; filter?: string;
  consistency_level?: ConsistencyLevelEnum;
}): Promise<{ id: unknown; neighbours: { id: unknown; score: number }[] }[]> {
  const response = ok(await client.query({
    collection_name: args.collection_name,
    filter: args.filter ?? "",
    output_fields: [args.primary_key, args.field],
    limit: args.sample ?? 100,
    ...(args.consistency_level ? { consistency_level: args.consistency_level } : {}),
  }));
  const rows = response.data as Row[];
  return rows.map((row) => ({
    id: row[args.primary_key],
    neighbours: rows
      .filter((other) => other[args.primary_key] !== row[args.primary_key])
      .map((other) => ({ id: other[args.primary_key], score: pairwise(args.metric, row[args.field] as number[], other[args.field] as number[]) }))
      .sort((a, b) => b.score - a.score)
      .slice(0, args.limit ?? 10),
  }));
}

export async function compact(client: MilvusClient, args: { collection_name: string; wait?: boolean }): Promise<Row> {
  const response = ok(await client.compact({ collection_name: args.collection_name }));
  const compactionID = response.compactionID;
  if (args.wait === false) {
    return { compaction_id: compactionID };
  }
  for (;;) {
    const state = String(ok(await client.getCompactionState({ compactionID })).state);
    if (state.toLowerCase() === "completed") {
      return { compaction_id: compactionID, state };
    }
    await sleep(1000);
  }
}

export async function awaitIndex(client: MilvusClient, args: {
  collection_name: string; index_name: string; field_name: string; until?: string; timeout?: number;
}): Promise<Row> {
  const deadline = args.timeout === undefined ? undefined : Date.now() + args.timeout * 1000;
  for (;;) {
    let response = await client.describeIndex({ collection_name: args.collection_name, index_name: args.index_name });
    if (response.index_descriptions.length === 0) {
      response = await client.describeIndex({ collection_name: args.collection_name, field_name: args.field_name });
    }
    const info = ok(response).index_descriptions[0] as unknown as Row;
    const state = String(info.state ?? "Finished").toLowerCase();
    if (state.includes("fail")) {
      if (args.until === "failed") {
        return info;
      }
      throw new Error(`index ${args.index_name} on ${args.collection_name} failed: ${String(info.index_state_fail_reason ?? "")}`);
    }
    if (args.until === "pending" || args.until === "building" || (state === "finished" && !Number(info.pending_index_rows ?? 0))) {
      return info;
    }
    if (deadline !== undefined && Date.now() > deadline) {
      throw new Error(`index ${args.index_name} on ${args.collection_name} not ready within ${args.timeout} s`);
    }
    await sleep(1000);
  }
}

export async function describe(client: MilvusClient, args: {
  collection_name: string; stats?: boolean; index_progress?: boolean;
}): Promise<Row> {
  const result: Row = { collection: ok(await client.describeCollection({ collection_name: args.collection_name })) };
  if (args.stats) {
    result.stats = ok(await client.getCollectionStatistics({ collection_name: args.collection_name }));
  }
  if (args.index_progress) {
    result.indexes = ok(await client.describeIndex({ collection_name: args.collection_name })).index_descriptions;
  }
  return result;
}

export async function listObjects(client: MilvusClient, args: {
  kind: string; scope?: string; prefix?: string; limit?: number; only?: string[];
}): Promise<string[]> {
  let names: string[];
  switch (args.kind) {
    case "collections":
      names = ok(await client.showCollections()).data.map((collection) => collection.name);
      break;
    case "databases":
      names = ok(await client.listDatabases()).db_names;
      break;
    case "indexes":
      names = ok(await client.listIndexes({ collection_name: args.scope ?? "" })).indexes;
      break;
    case "partitions":
      names = ok(await client.showPartitions({ collection_name: args.scope ?? "" })).partition_names;
      break;
    case "aliases":
      names = ok(await client.listAliases({ collection_name: args.scope ?? "" })).aliases;
      break;
    case "tenants":
    case "namespaces":
      names = ok(await client.showPartitions({ collection_name: args.scope ?? "" })).partition_names
        .filter((name) => (args.only ?? []).includes(name));
      break;
    case "snapshots": {
      const owners = args.scope ? [args.scope] : ok(await client.showCollections()).data.map((collection) => collection.name);
      names = [];
      for (const owner of owners) {
        names.push(...ok(await client.listSnapshots({ collection_name: owner })).snapshots);
      }
      names.sort();
      break;
    }
    default:
      return unsupported("milvus", `listing ${args.kind}`);
  }
  names = names.filter((name) => !args.prefix || name.startsWith(args.prefix)).sort();
  return args.limit ? names.slice(0, args.limit) : names;
}

export async function hasPartition(client: MilvusClient, args: { collection_name: string; partition_name: string }): Promise<boolean> {
  return Boolean(ok(await client.hasPartition(args)).value);
}

export async function dropField(client: MilvusClient, args: { collection_name: string; field_name: string }): Promise<void> {
  ok(await client.dropCollectionField({ collection_name: args.collection_name, field_name: args.field_name }));
}

export async function alterField(client: MilvusClient, args: {
  collection_name: string; field_name: string; field_params: Record<string, unknown>;
}): Promise<void> {
  ok(await client.alterCollectionFieldProperties({
    collection_name: args.collection_name,
    field_name: args.field_name,
    properties: args.field_params as Record<string, string | number | boolean>,
  }));
}

export async function addFileResource(client: MilvusClient, args: { name: string; path: string }): Promise<void> {
  ok(await client.addFileResource(args));
}

export async function removeFileResource(client: MilvusClient, args: { name: string }): Promise<void> {
  ok(await client.removeFileResource(args));
}

export const ANALYZER_PROBE = "vecDSL Analyzer CHECK";

/** Runs the analyzer on the server over a fixed text; the server rejects analyzer settings it cannot build. */
export async function checkAnalyzer(client: MilvusClient, args: { analyzer_params: Record<string, unknown> }): Promise<string[]> {
  const response = ok(await client.runAnalyzer({ text: ANALYZER_PROBE, analyzer_params: args.analyzer_params }));
  return response.results[0].tokens.map((token) => token.token);
}

function compareKeys(left: unknown, right: unknown): number {
  return typeof left === "number" && typeof right === "number" ? left - right : String(left).localeCompare(String(right));
}

async function keys(client: MilvusClient, collection: string, primaryKey: string, filter?: string, partitionNames?: string[]): Promise<unknown[]> {
  const rows = await scroll(client, {
    collection_name: collection, filter, output_fields: [primaryKey], ...(partitionNames ? { partition_names: partitionNames } : {}),
  });
  return rows.map((row) => row[primaryKey]).sort(compareKeys);
}

/** Deletes the matching records, or the first n in primary key order: Milvus deletes take no limit. */
export async function deleteMatching(client: MilvusClient, args: {
  collection_name: string; primary_key: string; filter?: string; partition_name?: string; limit?: number;
}): Promise<{ delete_count: number }> {
  let found = await keys(client, args.collection_name, args.primary_key, args.filter,
    args.partition_name ? [args.partition_name] : undefined);
  if (args.limit !== undefined) {
    found = found.slice(0, args.limit);
  }
  let deleted = 0;
  for (const chunk of batches(found, PAGE)) {
    deleted += (await deleteRows(client, { collection_name: args.collection_name, ids: chunk, partition_name: args.partition_name })).delete_count;
  }
  return { delete_count: deleted };
}

/** Exactly min(size, matches) records: a uniform draw over the matching keys, or the first ones in key order. */
export async function sampleRows(client: MilvusClient, args: {
  collection_name: string; primary_key: string; size: number; output_fields: string[]; first?: boolean; filter?: string;
  partition_names?: string[]; consistency_level?: unknown;
}): Promise<Row[]> {
  const found = await keys(client, args.collection_name, args.primary_key, args.filter, args.partition_names);
  let chosen: unknown[];
  if (args.first) {
    chosen = found.slice(0, args.size);
  } else {
    const pool = [...found];
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    chosen = pool.slice(0, Math.min(args.size, pool.length)).sort(compareKeys);
  }
  if (chosen.length === 0) {
    return [];
  }
  const rows = await getRows(client, {
    collection_name: args.collection_name, ids: chosen, output_fields: [args.primary_key, ...args.output_fields],
    ...(args.partition_names ? { partition_names: args.partition_names } : {}),
  });
  const byKey = new Map(rows.map((row) => [String(row[args.primary_key]), row]));
  return chosen.map((key) => byKey.get(String(key)) as Row);
}

/** POST to the Milvus RESTful API v2 at the endpoint the client was opened with (for calls the SDK lacks). */
async function rest(client: MilvusClient, path: string, body: Record<string, unknown>): Promise<Record<string, unknown>> {
  const config = endpoints.get(client);
  if (config === undefined) {
    throw new Error("the client was not opened with rt.connect, so its REST endpoint is unknown");
  }
  const base = /^https?:\/\//.test(config.address) ? config.address : `http://${config.address}`;
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  const token = config.token ?? (config.username ? `${config.username}:${config.password ?? ""}` : undefined);
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }
  const payload = config.database ? { dbName: config.database, ...body } : body;
  const response = await fetch(`${base.replace(/\/+$/, "")}/v2/vectordb${path}`, {
    method: "POST", headers, body: JSON.stringify(payload),
  });
  const reply = (await response.json()) as { code?: number; message?: string; data?: Record<string, unknown> };
  if ((reply.code ?? 0) !== 0) {
    throw new Error(`Milvus REST ${path} failed: ${reply.message ?? JSON.stringify(reply)}`);
  }
  return reply.data ?? {};
}

/** Starts a Milvus import job over files in the server's bucket and, unless asked not to, waits for it. */
export async function bulkImport(client: MilvusClient, args: {
  collection_name: string; files: string[][]; partition_name?: string; wait?: boolean;
}): Promise<Row> {
  const body: Record<string, unknown> = { collectionName: args.collection_name, files: args.files };
  if (args.partition_name) {
    body.partitionName = args.partition_name;
  }
  const jobId = String((await rest(client, "/jobs/import/create", body)).jobId);
  if (args.wait === false) {
    return { job_id: jobId };
  }
  for (;;) {
    const progress = await rest(client, "/jobs/import/describe", { jobId });
    if (progress.state === "Completed") {
      return { job_id: jobId, state: progress.state, imported_rows: Number(progress.importedRows ?? 0) };
    }
    if (progress.state === "Failed") {
      throw new Error(`import job ${jobId} into ${args.collection_name} failed: ${String(progress.reason ?? "")}`);
    }
    await sleep(1000);
  }
}

/**
 * Flushes and waits until the channel checkpoint passes the flush timestamp, as pymilvus and the Java SDK do; the Node SDK's
 * flushSync waits only for the segments, so a snapshot taken after it can miss the latest deletes. Like those SDKs, it retries
 * while the server's flush rate limit (one flush per collection every 10 s by default) rejects the request.
 */
async function flushToCheckpoint(client: MilvusClient, collection: string): Promise<void> {
  const deadline = Date.now() + 60000;
  let flushed: FlushResult & { coll_flush_ts?: Record<string, number | string> };
  for (;;) {
    try {
      flushed = ok(await client.flush({ collection_names: [collection] }));
      break;
    } catch (error) {
      if (!/rate ?limit/i.test(String(error)) || Date.now() > deadline) {
        throw error;
      }
      await sleep(1000);
    }
  }
  // int64 ids and timestamps stay as the SDK returns them (strings), which Number would round
  const segmentIDs = (flushed.coll_segIDs?.[collection]?.data ?? []) as unknown as number[];
  const flushTs = flushed.coll_flush_ts?.[collection];
  for (;;) {
    const state = ok(await client.getFlushState({
      segmentIDs, collection_name: collection, ...(flushTs !== undefined ? { flush_ts: flushTs as unknown as number } : {}),
    }));
    if (state.flushed) {
      return;
    }
    await sleep(500);
  }
}

export async function dropAliases(client: MilvusClient, args: { collection_name: string }): Promise<void> {
  for (const alias of ok(await client.listAliases({ collection_name: args.collection_name })).aliases) {
    ok(await client.dropAlias({ alias }));
  }
}

/** Flushes first: a snapshot records sealed segments, so writes and deletes still in memory would be missing. */
export async function createSnapshot(client: MilvusClient, args: {
  collection_name: string; snapshot_name: string; description?: string;
}): Promise<void> {
  await flushToCheckpoint(client, args.collection_name);
  ok(await client.createSnapshot(args));
}

async function snapshotOwner(client: MilvusClient, snapshot: string): Promise<string> {
  const owners: string[] = [];
  for (const collection of ok(await client.showCollections()).data) {
    if (ok(await client.listSnapshots({ collection_name: collection.name })).snapshots.includes(snapshot)) {
      owners.push(collection.name);
    }
  }
  if (owners.length !== 1) {
    throw new Error(`snapshot ${snapshot} belongs to ${owners.length} collections; name its collection`);
  }
  return owners[0];
}

/** Restores a snapshot into a new collection and, when waiting, loads it so it serves queries. */
export async function restoreSnapshot(client: MilvusClient, args: {
  snapshot_name: string; collection_name: string; source_collection_name?: string; wait?: boolean;
}): Promise<Row> {
  const source = args.source_collection_name ?? await snapshotOwner(client, args.snapshot_name);
  const jobId = ok(await client.restoreSnapshot({
    snapshot_name: args.snapshot_name, source_collection_name: source, target_collection_name: args.collection_name,
  })).job_id;
  if (args.wait === false) {
    return { job_id: jobId };
  }
  for (;;) {
    const info = ok(await client.getRestoreSnapshotState({ job_id: jobId })).info;
    const state = String(info.state);
    if (state === "RestoreSnapshotCompleted") {
      ok(await client.loadCollectionSync({ collection_name: args.collection_name }));
      return { job_id: jobId, state };
    }
    if (state === "RestoreSnapshotFailed") {
      throw new Error(`restoring ${args.snapshot_name} into ${args.collection_name} failed: ${info.reason}`);
    }
    await sleep(1000);
  }
}

export async function dropSnapshot(client: MilvusClient, args: { snapshot_name: string; collection_name?: string }): Promise<void> {
  const owner = args.collection_name ?? await snapshotOwner(client, args.snapshot_name);
  ok(await client.dropSnapshot({ collection_name: owner, snapshot_name: args.snapshot_name }));
}

/** A materialized copy: a temporary snapshot restored under the new name, then dropped. */
export async function cloneCollection(client: MilvusClient, args: { collection_name: string; target_name: string }): Promise<Row> {
  const snapshot = `vecdsl_clone_${args.target_name}`;
  await createSnapshot(client, { collection_name: args.collection_name, snapshot_name: snapshot });
  try {
    await restoreSnapshot(client, { snapshot_name: snapshot, collection_name: args.target_name, source_collection_name: args.collection_name });
  } finally {
    await dropSnapshot(client, { snapshot_name: snapshot, collection_name: args.collection_name });
  }
  return { collection: args.target_name, count: await count(client, { collection_name: args.target_name }) };
}

export function jsonReplacer(_key: string, value: unknown): unknown {
  return typeof value === "bigint" ? value.toString() : value;
}
